"""Origin framing and evidence audit extension.

Channels are compressed byte captures: parts are byte-program nodes that may
describe petabytes of repeated boundary probes.  The reader below therefore
parses HTTP/1.1 framing *without* expanding a capture -- only lines (bounded by
8192 bytes) and field blocks (bounded by 65536 bytes) are materialised, bodies
are summarised by exact fingerprint over their compressed ranges, and chunk
runs are aggregated arithmetically.
"""
import re
from bisect import bisect_right

from modules import byte_program as bp
from modules.byte_program import MAX, cat, fingerprint, lit_hash, p257, rhash

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")

LINE_LIMIT = 8192            # bytes before CRLF
LINE_WINDOW = LINE_LIMIT + 2  # search window that reproduces the documented rules
BLOCK_LIMIT = 65536          # initial/trailer block bytes
FIELD_LIMIT = 128            # fields per block
REQUEST_BUDGET = 20000       # complete requests examined, all channels
CHUNK_LINE_BUDGET = 40000    # chunk-size lines examined, all channels

VISIBLE = bytes(range(0x21, 0x7f))
FIELD_OK = b'\t' + bytes(range(0x20, 0x7f))
DIGITS = b'0123456789'
HEXDIGITS = b'0123456789abcdefABCDEF'
FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')
EMPTY_FP = {'n': 0, 'h': '0' * 16}


class Incomplete(Exception):
    """The capture stopped in the middle of a request."""


class Malformed(Exception):
    """A completed line/field/body violated the framing rules."""


class BudgetError(ValueError):
    """More requests or chunk-size lines than the audit may examine."""


class Budget:
    __slots__ = ('requests', 'chunk_lines')

    def __init__(self):
        self.requests = 0
        self.chunk_lines = 0


class Reader:
    """Line/byte access over one compressed channel node."""
    __slots__ = ('node', 'length', 'pos', 'budget')

    def __init__(self, node, budget):
        self.node = node
        self.length = node.n
        self.pos = 0
        self.budget = budget

    def remaining(self):
        return self.length - self.pos

    def line(self, chunk_position=False):
        """Next CRLF terminated line as bytes, without its terminator."""
        node = self.node
        start = self.pos
        stop = start + LINE_WINDOW
        if stop > self.length:
            stop = self.length
        found = bp.find_lf(node, start, stop)
        if found < 0:
            if self.length - start <= LINE_LIMIT + 1:
                raise Incomplete()
            raise Malformed()
        raw = bytes(bp.read_bytes(node, start, found + 1))
        if len(raw) < 2 or raw[-2] != 0x0d:
            # bare LF, or an LF beyond the line limit
            raise Malformed()
        self.pos = found + 1
        if chunk_position:
            self.budget.chunk_lines += 1
            if self.budget.chunk_lines > CHUNK_LINE_BUDGET:
                raise BudgetError('chunk-size line budget')
        return raw[:-2]

    def take(self, count):
        """Consume ``count`` opaque body bytes; returns their half-open span."""
        if self.remaining() < count:
            raise Incomplete()
        start = self.pos
        self.pos = start + count
        return start, self.pos


def _field(name, value):
    if not TOKEN.fullmatch(name):
        raise Malformed()
    if value.translate(None, FIELD_OK):
        raise Malformed()
    return name, value.strip(b' \t')


def _read_fields(reader, block):
    """Header/trailer field block; ``block`` already counts earlier lines."""
    fields = []
    while True:
        line = reader.line()
        if not line:
            block += 2
            if block > BLOCK_LIMIT:
                raise Malformed()
            return fields, block
        colon = line.find(b':')
        if colon <= 0:
            raise Malformed()
        fields.append(_field(line[:colon], line[colon + 1:]))
        block += len(line) + 2
        if block > BLOCK_LIMIT or len(fields) > FIELD_LIMIT:
            raise Malformed()


def _content_length(fields):
    values = [value for name, value in fields
              if name.lower() == b'content-length']
    if not values:
        return None
    declared = None
    for value in values:
        for member in value.split(b','):
            member = member.strip(b' \t')
            if not member or member.translate(None, DIGITS):
                raise Malformed()
            number = int(member)
            if number > MAX:
                raise Malformed()
            if declared is None:
                declared = number
            elif number != declared:
                raise Malformed()
    return declared


def _framing(fields):
    """Resolve body framing: (mode, length)."""
    lengths = [value for name, value in fields if name.lower() == b'content-length']
    encodings = [value for name, value in fields
                 if name.lower() == b'transfer-encoding']
    if encodings:
        if len(encodings) != 1 or lengths:
            raise Malformed()
        if encodings[0].lower() != b'chunked':
            raise Malformed()
        return 'chunked', None
    if lengths:
        return 'length', _content_length(fields)
    return 'none', 0


def _body_of_chunked(reader):
    """Deframe a chunked body; returns (spans, trailer fields)."""
    node = reader.node
    spans = []
    total = 0
    while True:
        line = reader.line(chunk_position=True)
        semi = line.find(b';')
        if semi < 0:
            size_text, suffix = line, None
        else:
            size_text, suffix = line[:semi], line[semi + 1:]
        if not size_text or size_text.translate(None, HEXDIGITS):
            raise Malformed()
        if suffix is not None and suffix.translate(None, FIELD_OK):
            raise Malformed()
        size = int(size_text, 16)
        if size > MAX:
            raise Malformed()
        if size == 0:
            trailers, _ = _read_fields(reader, 0)
            for name, _value in trailers:
                if name.lower() in FORBIDDEN_TRAILER:
                    raise Malformed()
            return spans, total, trailers
        start, stop = reader.take(size)
        spans.append((start, stop))
        total += size
        if total > MAX:
            raise Malformed()
        if reader.remaining() < 2:
            raise Incomplete()
        crlf = bytes(bp.read_bytes(node, reader.pos, reader.pos + 2))
        if crlf != b'\r\n':
            raise Malformed()
        reader.pos += 2


def _fold(node, spans):
    acc = 0
    total = 0
    for start, stop in spans:
        acc = (acc * p257(stop - start) + rhash(node, start, stop)) & bp.MASK
        total += stop - start
        if total > MAX:
            raise Malformed()
    return {'n': total, 'h': '%016x' % acc}


def encode_fields(fields):
    """Exact field-block encoding used for header/trailer fingerprints."""
    pieces = [len(fields).to_bytes(8, 'big')]
    for name, value in fields:
        pieces.append(len(name).to_bytes(8, 'big'))
        pieces.append(name)
        pieces.append(len(value).to_bytes(8, 'big'))
        pieces.append(value)
    return b''.join(pieces)


def parse_requests(node, budget):
    """Parse consecutive HTTP/1.1 requests from byte 0 of one channel."""
    reader = Reader(node, budget)
    requests = []
    error = None
    while reader.pos < reader.length:
        start = reader.pos
        try:
            line = reader.line()
            parts = line.split(b' ')
            if len(parts) != 3:
                raise Malformed()
            method, target, version = parts
            if not TOKEN.fullmatch(method):
                raise Malformed()
            if not target or target.translate(None, VISIBLE):
                raise Malformed()
            if version != b'HTTP/1.1':
                raise Malformed()
            fields, _ = _read_fields(reader, len(line) + 2)
            mode, declared = _framing(fields)
            trailers = []
            if mode == 'none':
                body = EMPTY_FP
            elif mode == 'length':
                span = reader.take(declared)
                body = {'n': declared,
                        'h': '%016x' % rhash(node, span[0], span[1])} if declared else EMPTY_FP
            else:
                spans, _total, trailers = _body_of_chunked(reader)
                body = _fold(node, spans) if spans else EMPTY_FP
        except Incomplete:
            error = {'kind': 'incomplete', 'offset': start}
            break
        except Malformed:
            error = {'kind': 'syntax', 'offset': start}
            break
        budget.requests += 1
        if budget.requests > REQUEST_BUDGET:
            raise BudgetError('request budget')
        hosts = [value for name, value in fields if name.lower() == b'host']
        requests.append({
            'start': start,
            'end': reader.pos,
            'method': {'n': len(method), 'h': '%016x' % lit_hash(method)},
            'target': {'n': len(target), 'h': '%016x' % lit_hash(target)},
            'host': fingerprint_of(hosts[0].lower()) if len(hosts) == 1 else EMPTY_FP,
            'host_bytes': hosts[0].lower() if len(hosts) == 1 else b'',
            'host_count': len(hosts),
            'headers': fingerprint_of(encode_fields(fields)),
            'body': body,
            'trailers': fingerprint_of(encode_fields(trailers)),
            'framing': mode,
        })
    return requests, error


def fingerprint_of(data):
    return {'n': len(data), 'h': '%016x' % lit_hash(data)}


class Attribution:
    """Maps byte spans of one channel onto part provenance labels."""
    __slots__ = ('spans', 'starts')

    def __init__(self, parts):
        spans = []
        offset = 0
        for label, node in parts:
            span = node.n
            if span:
                spans.append((offset, offset + span, label))
            offset += span
            if offset > MAX:
                raise ValueError('channel length overflow')
        self.spans = spans
        self.starts = [span[0] for span in spans]
        self.length = offset

    def owners(self, start, stop):
        spans = self.spans
        index = bisect_right(self.starts, start) - 1
        if index < 0:
            index = 0
        out = []
        while index < len(spans) and spans[index][0] < stop:
            low, high, label = spans[index]
            lo = low if low > start else start
            hi = high if high < stop else stop
            if hi > lo:
                if out and out[-1][0] == label:
                    out[-1][1] += hi - lo
                else:
                    out.append([label, hi - lo])
            index += 1
        return out


def audit_channels(channels, expects, sent_frames):
    """Audit every capture; returns channel records and per-case provenance."""
    budget = Budget()
    records = []
    origin = {name: {'count': 0, 'identity': False, 'mixed': False}
              for name in expects}
    seen_owner = set()
    for channel in channels:
        node = cat([node for _label, node in channel['parts']])
        if node.n > MAX:
            raise ValueError('channel length overflow')
        attribution = Attribution(channel['parts'])
        requests, error = parse_requests(node, budget)
        published = []
        ends = []
        for request in requests:
            owners = attribution.owners(request['start'], request['end'])
            owner = owners[0][0] if owners else None
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if len(owners) > 1:
                flags.add('mixed_owner')
            if request['host_count'] == 0:
                flags.add('missing_host')
            elif request['host_count'] > 1:
                flags.add('multiple_host')
            if owner is not None:
                expect = expects[owner]
                if (request['method']['h'] != '%016x' % lit_hash(expect['method'])
                        or request['method']['n'] != len(expect['method'])):
                    flags.add('identity')
                elif (request['target']['n'] != len(expect['target'])
                        or request['target']['h'] != '%016x' % lit_hash(expect['target'])):
                    flags.add('identity')
                if request['host_count'] != 1 or request['host_bytes'] != expect['host_folded']:
                    flags.add('identity')
                if owner in seen_owner:
                    flags.add('extra')
                else:
                    seen_owner.add(owner)
                if not sent_frames.get(owner, 0):
                    flags.add('unsent')
                state = origin[owner]
                state['count'] += 1
                if 'identity' in flags:
                    state['identity'] = True
                if 'mixed_owner' in flags:
                    state['mixed'] = True
            record = {
                'start': request['start'],
                'end': request['end'],
                'method': request['method'],
                'target': request['target'],
                'host': request['host'],
                'host_count': request['host_count'],
                'headers': request['headers'],
                'body': request['body'],
                'trailers': request['trailers'],
                'framing': request['framing'],
                'owner': owner,
                'owners': [[label, count] for label, count in owners],
                'flags': sorted(flags),
            }
            published.append(record)
            ends.append(request['end'])
        committed = []
        offset = 0
        for _label, part in channel['parts']:
            offset += part.n
            committed.append(bisect_right(ends, offset))
        records.append({
            'name': channel['name'],
            'bytes': fingerprint(node),
            'requests': published,
            'committed': committed,
            'error': error,
        })
    return records, origin


def case_flags(origin_state, request_frames):
    flags = set()
    count = origin_state['count']
    if request_frames > 0 and count == 0:
        flags.add('missing_origin')
    if count > 1:
        flags.add('extra_origin')
    if count > 0 and request_frames == 0:
        flags.add('unsent_origin')
    if origin_state['identity']:
        flags.add('identity')
    if origin_state['mixed']:
        flags.add('mixed_origin')
    return sorted(flags)
